// Tabla de pedidos: clave compuesta y dos índices globales, uno por patrón que no cabe en la clave primaria.
export const tabla = {
  partitionKey: "clienteId",
  sortKey: "pedidoId",
  gsis: [
    // Pedidos por estado, ordenados por fecha; proyecta total porque un GSI no lee atributos de la tabla.
    { name: "EstadoFechaIndex", partitionKey: "estado", sortKey: "fechaPedido", projection: { type: "INCLUDE", attributes: ["total"] } },
    // Pedidos por producto; con solo las claves basta.
    { name: "ProductoFechaIndex", partitionKey: "productoId", sortKey: "fechaPedido", projection: { type: "KEYS_ONLY" } },
  ],
};

// Con el arnés: aws.dynamodb.validateTable(tabla) debe dar [] y
// aws.dynamodb.planAccessPatterns(tabla, patrones) devuelve, por patrón, { operation, index, problems }.
// Un patrón sin clave ni índice que lo resuelva devuelve operation: null y un problema (solo se resolvería con un recorrido completo).

