spec.code:
const patrones = [
  { name: "perfilDeJugador", keyCondition: [{ attribute: "jugadorId", operator: "=" }, { attribute: "juego", operator: "=" }], requiredAttributes: ["apodo"] },
  { name: "mejoresDeUnJuego", keyCondition: [{ attribute: "juego", operator: "=" }, { attribute: "puntos", operator: ">=" }], requiredAttributes: ["apodo", "puntos"] },
];
const planes = aws.dynamodb.planAccessPatterns(tabla, patrones);
assert.strictEqual(planes[1].operation, "Query");
assert.strictEqual(planes[1].index, "JuegoPuntosIndex");
assert.deepStrictEqual(planes[1].problems, [], "El índice debe proyectar los atributos que pide el patrón");

const patrones = [
  { name: "perfilDeJugador", keyCondition: [{ attribute: "jugadorId", operator: "=" }, { attribute: "juego", operator: "=" }], requiredAttributes: ["apodo"] },
  { name: "mejoresDeUnJuego", keyCondition: [{ attribute: "juego", operator: "=" }, { attribute: "puntos", operator: ">=" }], requiredAttributes: ["apodo", "puntos"] },
];
const planes = aws.dynamodb.planAccessPatterns(tabla, patrones);
assert.strictEqual(planes[0].operation, "GetItem");
assert.strictEqual(planes[0].index, null);
assert.deepStrictEqual(planes[0].problems, []);

const indice = tabla.gsis.find((g) => g.name === "JuegoPuntosIndex");
assert.ok(indice, "El índice JuegoPuntosIndex debe seguir existiendo");
assert.strictEqual(indice.projection.type, "INCLUDE");
assert.deepStrictEqual(indice.projection.attributes, ["apodo"]);

const indice = tabla.gsis.find((g) => g.name === "JuegoPuntosIndex");
assert.strictEqual(tabla.partitionKey, "jugadorId");
assert.strictEqual(tabla.sortKey, "juego");
assert.strictEqual(indice.partitionKey, "juego");
assert.strictEqual(indice.sortKey, "puntos");
assert.strictEqual(tabla.gsis.length, 1);

